import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyCuDan = () => {
    // State lưu phòng đang được chọn
    const [selectedRoom, setSelectedRoom] = useState(null);

    // Dữ liệu ban đầu để trống hoàn toàn
    const databaseResidents = {}; 

    // Tạo danh sách 45 phòng (Tầng 1-9)
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // Logic lấy thông tin
    const getResidentInfo = (roomId) => {
        return databaseResidents[roomId] || {
            name: "Chưa có dữ liệu",
            gender: "---",
            phone: "---",
            members: 0,
            parking: "---"
        };
    };

    const info = selectedRoom ? getResidentInfo(selectedRoom) : null;

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý cư dân</h2>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG */}
                <div style={{ 
                    width: '210px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '12px',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px',
                    border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setSelectedRoom(room)}
                            style={{ 
                                background: selectedRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                color: selectedRoom === room ? 'white' : '#333',
                                padding: '8px 0', 
                                borderRadius: '8px', 
                                textAlign: 'center', 
                                fontSize: '11px', 
                                fontWeight: 'bold', 
                                cursor: 'pointer',
                                transition: '0.3s',
                                boxShadow: selectedRoom === room ? '0 4px 10px rgba(0,0,0,0.3)' : 'none'
                            }}
                        >
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT CƯ DÂN (NỀN TRẮNG CHỮ ĐEN) */}
                <div style={{ 
                    flex: 1, 
                    backgroundColor: '#ffffff', // Đổi từ mờ sang trắng đặc
                    borderRadius: '25px', 
                    padding: '40px',
                    display: 'flex',
                    flexDirection: 'column',
                    color: '#000', // Chữ đen hoàn toàn để rõ nét
                    boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)'
                }}>
                    {selectedRoom ? (
                        <div style={{ animation: 'fadeIn 0.5s' }}>
                            {/* Số phòng hiển thị màu đỏ nâu để tạo điểm nhấn */}
                            <h1 style={{ 
                                fontSize: '60px', 
                                margin: '0 0 40px 0', 
                                color: '#8b5e5e',
                                borderBottom: '2px solid #eee', 
                                paddingBottom: '10px',
                                fontWeight: '800'
                            }}>
                                PHÒNG: {selectedRoom}
                            </h1>

                            {/* Danh sách thông tin dạng dòng - Chữ đen trên nền trắng */}
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '25px', fontSize: '20px' }}>
                                <div style={{ display: 'flex', alignItems: 'center' }}>
                                    <span style={{ width: '280px', fontWeight: 'bold', color: '#555' }}>Tên chủ phòng:</span>
                                    <span style={{ fontWeight: '600' }}>{info.name}</span>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center' }}>
                                    <span style={{ width: '280px', fontWeight: 'bold', color: '#555' }}>Giới tính:</span>
                                    <span>{info.gender}</span>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center' }}>
                                    <span style={{ width: '280px', fontWeight: 'bold', color: '#555' }}>Liên hệ (SĐT):</span>
                                    <span>{info.phone}</span>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center' }}>
                                    <span style={{ width: '280px', fontWeight: 'bold', color: '#555' }}>Số lượng thành viên:</span>
                                    <span>{info.members} người</span>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center' }}>
                                    <span style={{ width: '280px', fontWeight: 'bold', color: '#555' }}>Bãi đỗ xe:</span>
                                    <span>{info.parking}</span>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div style={{ 
                            flex: 1, 
                            display: 'flex', 
                            justifyContent: 'center', 
                            alignItems: 'center', 
                            color: '#999', 
                            fontSize: '22px', 
                            fontStyle: 'italic' 
                        }}>
                            Vui lòng chọn một phòng bên trái để xem thông tin...
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default QuanLyCuDan;
